DROP TABLE IF EXISTS `sourcelead`.`SOURCELEAD_SIGNATURE`;
CREATE TABLE `sourcelead`.`SOURCELEAD_SIGNATURE` (
  ID BIGINT NOT NULL AUTO_INCREMENT,
  LABEL_NAME VARCHAR(100) DEFAULT NULL,
  LABEL_TEXT VARCHAR(100) DEFAULT NULL,
  FONT_FAMILY VARCHAR(50) DEFAULT NULL,
  FONT_SIZE VARCHAR(10) DEFAULT NULL,
  FONT_COLOR VARCHAR(20) DEFAULT NULL,
  FONT_STYLE VARCHAR(100) DEFAULT NULL,
  STATUS INT DEFAULT NULL,
  CREATED_DATE DATE,
  CREATED_BY VARCHAR(10),
  UPDATED_DATE DATE,
  UPDATED_BY VARCHAR(10),
  PRIMARY KEY (`ID`)
); 


